-- ============================================================================
-- NodaPos Full Data Migration: kasa SQLite → cloud Postgres
-- StoreId: 33420AB3-5349-422C-838C-15DBC6E94730 (Fresh Pizza)
-- ============================================================================
-- İçerir: stores, customers, addresses, calls, orders, items, item_options, payments
-- Atlanır: users, supervisors (mimari kural — cloud yazımı)
-- Strateji: idempotent UPSERT (ON CONFLICT DO UPDATE). Veri kaybı yok.
-- Sıralama: calls.ResolvedOrderId ↔ orders.IncomingCallId circular FK'i nedeniyle
-- calls önce NULL ResolvedOrderId ile insert edilir, orders insert sonrası UPDATE.
-- ============================================================================

BEGIN;

-- STORES (1) — Fresh Pizza
ON CONFLICT ("Id") DO UPDATE SET "Name"=EXCLUDED."Name", "Address"=EXCLUDED."Address", "Phone"=EXCLUDED."Phone", "TaxNumber"=EXCLUDED."TaxNumber", "IsActive"=EXCLUDED."IsActive", "UpdatedAt"=NOW();

-- CUSTOMERS (1)
ON CONFLICT ("Id") DO UPDATE SET "Name"=EXCLUDED."Name", "Phone"=EXCLUDED."Phone", "Notes"=EXCLUDED."Notes", "IsActive"=EXCLUDED."IsActive", "UpdatedAt"=NOW();

-- CUSTOMER_ADDRESSES (1)
ON CONFLICT ("Id") DO UPDATE SET "CustomerId"=EXCLUDED."CustomerId", "Label"=EXCLUDED."Label", "AddressLine"=EXCLUDED."AddressLine", "District"=EXCLUDED."District", "Notes"=EXCLUDED."Notes", "IsDefault"=EXCLUDED."IsDefault", "UpdatedAt"=NOW();

-- INCOMING_CALLS (6) — ResolvedOrderId NULL geçici, orders sonrası UPDATE
ON CONFLICT ("Id") DO UPDATE SET "Phone"=EXCLUDED."Phone", "LineNumber"=EXCLUDED."LineNumber", "ReceivedAt"=EXCLUDED."ReceivedAt", "MatchedCustomerId"=EXCLUDED."MatchedCustomerId", "Status"=EXCLUDED."Status", "HandledByUserId"=EXCLUDED."HandledByUserId", "HandledAt"=EXCLUDED."HandledAt", "Note"=EXCLUDED."Note", "RawPayloadHex"=EXCLUDED."RawPayloadHex", "UpdatedAt"=NOW();

-- ORDERS (47)
ON CONFLICT ("Id") DO UPDATE SET "OrderNumber"=EXCLUDED."OrderNumber", "TableId"=EXCLUDED."TableId", "Status"=EXCLUDED."Status", "OrderType"=EXCLUDED."OrderType", "Subtotal"=EXCLUDED."Subtotal", "DiscountAmount"=EXCLUDED."DiscountAmount", "Total"=EXCLUDED."Total", "CustomerName"=EXCLUDED."CustomerName", "CustomerPhone"=EXCLUDED."CustomerPhone", "Notes"=EXCLUDED."Notes", "CustomerId"=EXCLUDED."CustomerId", "CustomerAddressId"=EXCLUDED."CustomerAddressId", "CompletedAt"=EXCLUDED."CompletedAt", "CancelledAt"=EXCLUDED."CancelledAt", "DeliveryAddressSnapshot"=EXCLUDED."DeliveryAddressSnapshot", "DeliveryDistrict"=EXCLUDED."DeliveryDistrict", "FulfillmentStatus"=EXCLUDED."FulfillmentStatus", "AssignedCourierUserId"=EXCLUDED."AssignedCourierUserId", "OutForDeliveryAt"=EXCLUDED."OutForDeliveryAt", "DeliveredAt"=EXCLUDED."DeliveredAt", "IncomingCallId"=EXCLUDED."IncomingCallId", "UpdatedAt"=NOW();

-- INCOMING_CALLS resolved-order linkage (1)
UPDATE incoming_calls SET "ResolvedOrderId" = 'e22582c9-c87e-43fd-bc8d-cc5c3a4697ca' WHERE "Id" = 'edce686d-d4ca-46ec-bed2-4dc9db546bfa';

-- ORDER_ITEMS (64)
ON CONFLICT ("Id") DO UPDATE SET "OrderId"=EXCLUDED."OrderId", "ProductId"=EXCLUDED."ProductId", "ProductName"=EXCLUDED."ProductName", "UnitPrice"=EXCLUDED."UnitPrice", "Quantity"=EXCLUDED."Quantity", "LineTotal"=EXCLUDED."LineTotal", "Notes"=EXCLUDED."Notes", "UpdatedAt"=NOW();

-- ORDER_ITEM_OPTIONS (35)
ON CONFLICT ("Id") DO UPDATE SET "OrderItemId"=EXCLUDED."OrderItemId", "ProductOptionId"=EXCLUDED."ProductOptionId", "GroupName"=EXCLUDED."GroupName", "OptionName"=EXCLUDED."OptionName", "AdditionalPrice"=EXCLUDED."AdditionalPrice", "UpdatedAt"=NOW();

-- PAYMENTS (37)
ON CONFLICT ("Id") DO UPDATE SET "OrderId"=EXCLUDED."OrderId", "Amount"=EXCLUDED."Amount", "Method"=EXCLUDED."Method", "PaidAt"=EXCLUDED."PaidAt", "ReferenceNumber"=EXCLUDED."ReferenceNumber", "Notes"=EXCLUDED."Notes", "UpdatedAt"=NOW();

COMMIT;

